screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブル再描画関数
  function renderOrders(orders) {
    const tbody = container.querySelector('#order-tbody');
    tbody.innerHTML = orders.map(order => {
      const statusBadge = getStatusBadge(order.発注ステータス);
      const integrationStatus = getIntegrationStatus(order.発注ID);
      const urgentBadge = order.緊急フラグ ? '<span class="px-1 py-0.5 text-xs rounded" style="background: #ff4444; color: #fff;">緊急</span>' : '';

      return `
        <tr data-id="${order.発注ID}" class="cursor-pointer hover:bg-opacity-50" style="hover:background: rgba(0,0,0,0.02);">
          <td>${order.発注番号 || ''}</td>
          <td>${order.発注日 ? new Date(order.発注日).toLocaleDateString() : ''}</td>
          <td>${order.発注先名 || ''}</td>
          <td class="text-right">¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td>${statusBadge}</td>
          <td>${integrationStatus}</td>
          <td>${urgentBadge}</td>
          <td>
            <button class="action-btn secondary detail-btn text-xs px-2 py-1" data-id="${order.発注ID}"
                    style="background: transparent; border: 1px solid rgba(255,255,255,0.18); color: var(--text);">
              詳細
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

  function getStatusBadge(status) {
    const colors = {
      '下書き': 'background: #6b7280; color: #fff;',
      '承認待ち': 'background: #f59e0b; color: #fff;',
      '承認済み': 'background: #10b981; color: #fff;',
      '発注済み': 'background: #3b82f6; color: #fff;',
      '完了': 'background: #059669; color: #fff;',
      'キャンセル': 'background: #ef4444; color: #fff;'
    };
    return `<span class="px-2 py-1 text-xs rounded" style="${colors[status] || 'background: #6b7280; color: #fff;'}">${status || ''}</span>`;
  }

  function getIntegrationStatus(orderId) {
    // 連携処理履歴から状況を判定（簡易実装）
    const integrationTable = tables.find(t => t.tableName === '連携処理履歴');
    if (integrationTable) {
      const history = integrationTable.records.find(r => r.対象データID === orderId);
      if (history) {
        if (history.処理ステータス === '成功') {
          return '<span class="px-2 py-1 text-xs rounded" style="background: #10b981; color: #fff;">連携済み</span>';
        } else if (history.処理ステータス === '失敗') {
          return '<span class="px-2 py-1 text-xs rounded" style="background: #ef4444; color: #fff;">エラー</span>';
        } else {
          return '<span class="px-2 py-1 text-xs rounded" style="background: #f59e0b; color: #fff;">処理中</span>';
        }
      }
    }
    return '<span class="px-2 py-1 text-xs rounded" style="background: #6b7280; color: #fff;">未連携</span>';
  }

  // KPI更新
  function updateKPIs(orders) {
    const totalOrders = orders.length;
    const totalAmount = orders.reduce((sum, order) => sum + (order.発注金額 || 0), 0);
    const pendingOrders = orders.filter(order => order.発注ステータス === '承認待ち').length;

    // エラー件数は連携エラーログから取得
    const errorTable = tables.find(t => t.tableName === '連携エラーログ');
    const errorCount = errorTable ? errorTable.records.filter(r => r.対応状況 === '未対応').length : 0;

    container.querySelector('#kpi-total-orders').textContent = totalOrders.toLocaleString();
    container.querySelector('#kpi-total-amount').textContent = `¥${totalAmount.toLocaleString()}`;
    container.querySelector('#kpi-error-count').textContent = errorCount.toLocaleString();
    container.querySelector('#kpi-pending-orders').textContent = pendingOrders.toLocaleString();
  }

  // グラフ初期化
  function initCharts(orders) {
    // 月別発注金額推移
    const monthlyData = {};
    orders.forEach(order => {
      if (order.発注日) {
        const month = order.発注日.slice(0, 7); // YYYY-MM
        monthlyData[month] = (monthlyData[month] || 0) + (order.発注金額 || 0);
      }
    });

    const monthlyLabels = Object.keys(monthlyData).sort();
    const monthlyValues = monthlyLabels.map(month => monthlyData[month]);

    new window.Chart(container.querySelector('#monthly-chart'), {
      type: 'line',
      data: {
        labels: monthlyLabels,
        datasets: [{
          label: '発注金額',
          data: monthlyValues,
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59, 130, 246, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });

    // ステータス分布
    const statusData = {};
    orders.forEach(order => {
      const status = order.発注ステータス || '不明';
      statusData[status] = (statusData[status] || 0) + 1;
    });

    new window.Chart(container.querySelector('#status-chart'), {
      type: 'doughnut',
      data: {
        labels: Object.keys(statusData),
        datasets: [{
          data: Object.values(statusData),
          backgroundColor: ['#6b7280', '#f59e0b', '#10b981', '#3b82f6', '#059669', '#ef4444']
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false
      }
    });
  }

  // 初期データ表示
  const orderTable = tables.find(t => t.tableName === '発注データ') || tables[0];
  const initialOrders = orderTable.records || [];
  renderOrders(initialOrders);
  updateKPIs(initialOrders);
  initCharts(initialOrders);

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const orderNo = container.querySelector('#search-order-no').value;
    const dateFrom = container.querySelector('#search-date-from').value;
    const dateTo = container.querySelector('#search-date-to').value;
    const status = container.querySelector('#search-status').value;
    const integration = container.querySelector('#search-integration').value;

    const orders = await window.aivicApi.list(0);
    if (!orders) return;

    const filtered = orders.filter(order => {
      if (orderNo && !order.発注番号?.includes(orderNo)) return false;
      if (dateFrom && order.発注日 && order.発注日 < dateFrom) return false;
      if (dateTo && order.発注日 && order.発注日> dateTo) return false;
      if (status && order.発注ステータス !== status) return false;
      if (integration) {
        const integrationStatus = getIntegrationStatus(order.発注ID);
        if (!integrationStatus.includes(integration)) return false;
      }
      return true;
    });

    renderOrders(filtered);
    updateKPIs(filtered);
  });

  // 条件クリア
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#search-order-no').value = '';
    container.querySelector('#search-date-from').value = '';
    container.querySelector('#search-date-to').value = '';
    container.querySelector('#search-status').value = '';
    container.querySelector('#search-integration').value = '';
    renderOrders(initialOrders);
    updateKPIs(initialOrders);
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const orders = await window.aivicApi.list(0);
    if (!orders) return;

    const headers = ['発注番号', '発注日', '発注先名', '発注金額', 'ステータス', '緊急フラグ'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...orders.map(order => [
        order.発注番号 || '',
        order.発注日 || '',
        order.発注先名 || '',
        order.発注金額 || 0,
        order.発注ステータス || '',
        order.緊急フラグ ? '緊急' : '通常'
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注データ_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 詳細モーダル
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const orderId = detailBtn.dataset.id;
      const orders = await window.aivicApi.list(0);
      const order = orders?.find(o => o.発注ID === orderId);

      if (order) {
        // 基本情報表示
        container.querySelector('#detail-order-no').textContent = order.発注番号 || '';
        container.querySelector('#detail-order-date').textContent = order.発注日 ? new Date(order.発注日).toLocaleDateString() : '';
        container.querySelector('#detail-supplier').textContent = order.発注先名 || '';
        container.querySelector('#detail-amount').textContent = `¥${(order.発注金額 || 0).toLocaleString()}`;

        // 発注明細表示
        const detailTable = tables.find(t => t.tableName === '発注明細データ');
        const details = detailTable ? detailTable.records.filter(d => d.発注ID === orderId) : [];
        const detailsTbody = container.querySelector('#detail-items-tbody');
        detailsTbody.innerHTML = details.map(detail => `
          <tr>
            <td>${detail.明細番号 || ''}</td>
            <td>${detail.商品コード || ''}</td>
            <td>${detail.商品名 || ''}</td>
            <td class="text-right">${detail.発注数量 || 0} ${detail.単位 || ''}</td>
            <td class="text-right">¥${(detail.単価 || 0).toLocaleString()}</td>
            <td class="text-right">¥${(detail.金額 || 0).toLocaleString()}</td>
          </tr>
        `).join('');

        // 連携状況・検証結果表示
        container.querySelector('#integration-status').innerHTML = `
          <div class="text-sm" style="color: var(--text);">${getIntegrationStatus(orderId)}</div>
        `;

        container.querySelector('#validation-result').innerHTML = `
          <div class="text-sm" style="color: var(--text);">検証完了</div>
          <div class="text-xs text-muted">データ整合性: OK</div>
        `;

        container.querySelector('#order-detail-modal').style.display = 'flex';
      }
    }
  });

  // モーダル閉じる
  container.querySelector('#close-modal').addEventListener('click', () => {
    container.querySelector('#order-detail-modal').style.display = 'none';
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const INTEGRATION_HISTORY_TABLE = 5; // 連携処理履歴
  const ERROR_LOG_TABLE = 6; // 連携エラーログ
  const VALIDATION_RESULT_TABLE = 7; // データ検証結果

  // 再描画関数の定義
  function renderProcessingRows(rows) {
    const tbody = container.querySelector("#processing-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.連携処理履歴ID?.substring(0, 8) || ""}</td>
        <td>${r.処理種別 || ""}</td>
        <td>${r.処理種別 || ""}</td>
        <td>${r.処理開始日時 ? new Date(r.処理開始日時).toLocaleString() : ""}</td>
        <td>
          <div class="w-full bg-gray-200 rounded-full h-2">
            <div class="bg-blue-600 h-2 rounded-full" style="width: ${Math.random() * 100}%"></div>
          </div>
        </td>
        <td>
          <span class="px-2 py-1 text-xs rounded" style="background: ${r.処理ステータス === '実行中' ? '#3b82f6' : '#6b7280'}; color: white;">
            ${r.処理ステータス || ""}
          </span>
        </td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
        </td>
      </tr>
    `).join("");
  }

  function renderHistoryRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.処理開始日時 ? new Date(r.処理開始日時).toLocaleString() : ""}</td>
        <td>${r.処理種別 || ""}</td>
        <td>${r.処理種別 || ""}</td>
        <td>${r.処理件数 || 0}</td>
        <td>${r.成功件数 || 0}</td>
        <td>${r.エラー件数 || 0}</td>
        <td>
          <span class="px-2 py-1 text-xs rounded" style="background: ${getStatusColor(r.処理ステータス)}; color: white;">
            ${r.処理ステータス || ""}
          </span>
        </td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary retry-btn" data-id="${r.id}">再実行</button>
        </td>
      </tr>
    `).join("");
  }

  function renderErrorRows(rows) {
    const tbody = container.querySelector("#error-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.エラー発生日時 ? new Date(r.エラー発生日時).toLocaleString() : ""}</td>
        <td>${r.エラー種別 || ""}</td>
        <td class="max-w-xs truncate">${r.エラーメッセージ || ""}</td>
        <td>
          <span class="px-2 py-1 text-xs rounded" style="background: ${getPriorityColor(r.重要度)}; color: white;">
            ${r.重要度 || ""}
          </span>
        </td>
        <td>${r.対応状況 || ""}</td>
        <td>
          <button class="action-btn secondary view-error-btn" data-id="${r.id}">詳細</button>
        </td>
      </tr>
    `).join("");
  }

  function getStatusColor(status) {
    switch(status) {
      case '成功': return '#10b981';
      case '失敗': return '#ef4444';
      case '実行中': return '#3b82f6';
      default: return '#6b7280';
    }
  }

  function getPriorityColor(priority) {
    switch(priority) {
      case '高': return '#ef4444';
      case '中': return '#f59e0b';
      case '低': return '#10b981';
      default: return '#6b7280';
    }
  }

  function updateStatusCounts() {
    Promise.all([
      window.aivicApi.list(INTEGRATION_HISTORY_TABLE),
      window.aivicApi.list(ERROR_LOG_TABLE)
    ]).then(([historyRows, errorRows]) => {
      const processingCount = historyRows.filter(r => r.処理ステータス === '実行中').length;
      const successCount = historyRows.filter(r => r.処理ステータス === '成功').length;
      const errorCount = errorRows.length;
      const totalCount = historyRows.length;

      container.querySelector("#processing-count").textContent = processingCount;
      container.querySelector("#success-count").textContent = successCount;
      container.querySelector("#error-count").textContent = errorCount;
      container.querySelector("#total-count").textContent = totalCount;
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(INTEGRATION_HISTORY_TABLE).then(rows => {
    if (rows) {
      const processingRows = rows.filter(r => r.処理ステータス === '実行中');
      renderProcessingRows(processingRows);
      renderHistoryRows(rows.slice(0, 10)); // 最新10件のみ表示
      updateStatusCounts();
    }
  });

  window.aivicApi.list(ERROR_LOG_TABLE).then(rows => {
    if (rows) {
      renderErrorRows(rows.slice(0, 10)); // 最新10件のみ表示
      updateStatusCounts();
    }
  });

  // 連携処理実行
  container.querySelector("#btn-execute-sync").addEventListener("click", async () => {
    const targetSystem = container.querySelector("#select-target-system").value;
    const processType = container.querySelector("#select-process-type").value;
    const startDateTime = container.querySelector("#input-start-datetime").value;
    const endDateTime = container.querySelector("#input-end-datetime").value;

    if (!targetSystem || !processType) {
      alert("連携対象システムと処理種別を選択してください。");
      return;
    }

    const newProcess = {
      連携設定ID: crypto.randomUUID(),
      処理種別: `${targetSystem}_${processType}`,
      処理ステータス: '実行中',
      処理開始日時: new Date().toISOString(),
      処理件数: 0,
      成功件数: 0,
      エラー件数: 0,
      再試行回数: 0
    };

    const saved = await window.aivicApi.save(INTEGRATION_HISTORY_TABLE, newProcess);
    if (saved) {
      alert("連携処理を開始しました。");
      // データを再読み込み
      window.aivicApi.list(INTEGRATION_HISTORY_TABLE).then(rows => {
        if (rows) {
          const processingRows = rows.filter(r => r.処理ステータス === '実行中');
          renderProcessingRows(processingRows);
          renderHistoryRows(rows.slice(0, 10));
          updateStatusCounts();
        }
      });
    }
  });

  // データ検証実行
  container.querySelector("#btn-validate-data").addEventListener("click", () => {
    window.showScreen("scr-1780291315061"); // データ検証結果画面
  });

  // 履歴検索
  container.querySelector("#btn-search-history").addEventListener("click", () => {
    const keyword = container.querySelector("#input-history-search").value;
    window.aivicApi.list(INTEGRATION_HISTORY_TABLE).then(rows => {
      if (rows) {
        const filtered = rows.filter(r => 
          JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
        );
        renderHistoryRows(filtered);
      }
    });
  });

  // 更新ボタン
  container.querySelector("#btn-refresh").addEventListener("click", () => {
    window.aivicApi.list(INTEGRATION_HISTORY_TABLE).then(rows => {
      if (rows) {
        const processingRows = rows.filter(r => r.処理ステータス === '実行中');
        renderProcessingRows(processingRows);
        renderHistoryRows(rows.slice(0, 10));
        updateStatusCounts();
      }
    });
  });

  // 画面遷移
  container.querySelector("#btn-history").addEventListener("click", () => {
    window.showScreen("scr-1780291323940"); // 連携処理履歴画面
  });

  container.querySelector("#btn-view-all-history").addEventListener("click", () => {
    window.showScreen("scr-1780291323940"); // 連携処理履歴画面
  });

  container.querySelector("#btn-error-analysis").addEventListener("click", () => {
    window.showScreen("scr-1780291305048"); // 連携エラー分析画面
  });

  // モーダル制御
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#process-detail-modal").style.display = "none";
  });

  // イベントデリゲーション
  container.addEventListener("click", async (e) => {
    const viewDetailBtn = e.target.closest(".view-detail-btn");
    const retryBtn = e.target.closest(".retry-btn");
    const viewErrorBtn = e.target.closest(".view-error-btn");

    if (viewDetailBtn) {
      const id = viewDetailBtn.dataset.id;
      const modal = container.querySelector("#process-detail-modal");
      const content = container.querySelector("#process-detail-content");

      // 詳細情報を取得して表示
      const rows = await window.aivicApi.list(INTEGRATION_HISTORY_TABLE);
      const record = rows?.find(r => r.id === id);

      if (record) {
        content.innerHTML = `
          <div class="space-y-3">
            <div><strong>処理ID:</strong> ${record.連携処理履歴ID || ""}</div>
            <div><strong>処理種別:</strong> ${record.処理種別 || ""}</div>
            <div><strong>開始日時:</strong> ${record.処理開始日時 ? new Date(record.処理開始日時).toLocaleString() : ""}</div>
            <div><strong>終了日時:</strong> ${record.処理終了日時 ? new Date(record.処理終了日時).toLocaleString() : "実行中"}</div>
            <div><strong>処理件数:</strong> ${record.処理件数 || 0}</div>
            <div><strong>成功件数:</strong> ${record.成功件数 || 0}</div>
            <div><strong>エラー件数:</strong> ${record.エラー件数 || 0}</div>
            <div><strong>ステータス:</strong> ${record.処理ステータス || ""}</div>
            ${record.エラーメッセージ ? `<div><strong>エラーメッセージ:</strong> ${record.エラーメッセージ}</div>` : ""}
          </div>
        `;
        modal.style.display = "flex";
      }
    }

    if (retryBtn) {
      const id = retryBtn.dataset.id;
      if (confirm("この処理を再実行しますか？")) {
        const updated = await window.aivicApi.update(INTEGRATION_HISTORY_TABLE, id, {
          処理ステータス: '実行中',
          再試行回数: 1,
          処理開始日時: new Date().toISOString()
        });
        if (updated) {
          alert("再処理を開始しました。");
          window.aivicApi.list(INTEGRATION_HISTORY_TABLE).then(rows => {
            if (rows) {
              renderHistoryRows(rows.slice(0, 10));
              updateStatusCounts();
            }
          });
        }
      }
    }

    if (viewErrorBtn) {
      window.showScreen("scr-1780291305048"); // 連携エラー分析画面
    }
  });
}

function(container, apiUrl, tables) {
  let currentErrors = [];
  let selectedErrorId = null;

  // テーブル再描画関数
  function renderErrors(errors) {
    const tbody = container.querySelector('#error-tbody');
    tbody.innerHTML = errors.map(error => `
      <tr data-id="${error.id}" class="cursor-pointer hover:bg-opacity-50" style="background: var(--bg-card);">
        <td>${new Date(error.エラー発生日時).toLocaleString()}</td>
        <td><span class="px-2 py-1 rounded text-xs" style="background: ${getErrorTypeColor(error.エラー種別)}; color: #fff;">${error.エラー種別}</span></td>
        <td>${error.連携システム名 || '-'}</td>
        <td>${error.発注データID ? `発注-${error.発注データID.slice(-8)}` : '-'}</td>
        <td class="max-w-xs truncate">${error.エラーメッセージ}</td>
        <td><span class="px-2 py-1 rounded text-xs" style="background: ${getPriorityColor(error.重要度)}; color: #fff;">${error.重要度}</span></td>
        <td><span class="px-2 py-1 rounded text-xs" style="background: ${getStatusColor(error.対応状況)}; color: #fff;">${error.対応状況}</span></td>
        <td>${error.対応者名 || '-'}</td>
        <td>
          <button class="action-btn secondary text-xs px-2 py-1 detail-btn" data-id="${error.id}">詳細</button>
          <button class="action-btn secondary text-xs px-2 py-1 reprocess-btn" data-id="${error.id}">再処理</button>
        </td>
      </tr>
    `).join('');

    updateSummary(errors);
    updateCharts(errors);
  }

  // サマリー更新
  function updateSummary(errors) {
    container.querySelector('#total-errors').textContent = errors.length;
    container.querySelector('#pending-errors').textContent = errors.filter(e => e.対応状況 === '未対応').length;
    container.querySelector('#processing-errors').textContent = errors.filter(e => e.対応状況 === '対応中').length;
    container.querySelector('#completed-errors').textContent = errors.filter(e => e.対応状況 === '対応完了').length;
  }

  // グラフ更新
  function updateCharts(errors) {
    drawTrendChart(errors);
    drawCategoryChart(errors);
  }

  // 時系列グラフ
  function drawTrendChart(errors) {
    const canvas = container.querySelector('#trend-chart');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 過去7日間のデータを集計
    const days = [];
    const counts = [];
    for (let i = 6; i >= 0; i--) {
      const date = new Date();
      date.setDate(date.getDate() - i);
      const dayStr = date.toISOString().split('T')[0];
      days.push(date.getMonth() + 1 + '/' + date.getDate());
      counts.push(errors.filter(e => e.エラー発生日時.startsWith(dayStr)).length);
    }

    const maxCount = Math.max(...counts, 1);
    const chartHeight = 150;
    const chartWidth = 250;
    const barWidth = chartWidth / days.length;

    // 軸線
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(30, 20);
    ctx.lineTo(30, chartHeight + 20);
    ctx.lineTo(chartWidth + 30, chartHeight + 20);
    ctx.stroke();

    // バー描画
    counts.forEach((count, i) => {
      const barHeight = (count / maxCount) * chartHeight;
      const x = 30 + i * barWidth + 5;
      const y = chartHeight + 20 - barHeight;

      ctx.fillStyle = '#00aa44';
      ctx.fillRect(x, y, barWidth - 10, barHeight);

      // ラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(days[i], x + (barWidth - 10) / 2, chartHeight + 35);
      ctx.fillText(count.toString(), x + (barWidth - 10) / 2, y - 5);
    });
  }

  // 円グラフ
  function drawCategoryChart(errors) {
    const canvas = container.querySelector('#category-chart');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const categories = {};
    errors.forEach(error => {
      categories[error.エラー種別] = (categories[error.エラー種別] || 0) + 1;
    });

    const total = errors.length;
    if (total === 0) return;

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = 70;

    let startAngle = 0;
    const colors = ['#ff6a00', '#0066cc', '#00aa44', '#cc0066'];
    let colorIndex = 0;

    Object.entries(categories).forEach(([category, count]) => {
      const sliceAngle = (count / total) * 2 * Math.PI;

      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, startAngle, startAngle + sliceAngle);
      ctx.closePath();
      ctx.fillStyle = colors[colorIndex % colors.length];
      ctx.fill();

      // ラベル
      const labelAngle = startAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius + 20);
      const labelY = centerY + Math.sin(labelAngle) * (radius + 20);

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(category, labelX, labelY);
      ctx.fillText(`${count}件`, labelX, labelY + 12);

      startAngle += sliceAngle;
      colorIndex++;
    });
  }

  // 色取得関数
  function getErrorTypeColor(type) {
    const colors = {
      'データ検証エラー': '#ff6a00',
      '通信エラー': '#0066cc', 
      'システムエラー': '#cc0066',
      '認証エラー': '#aa6600'
    };
    return colors[type] || '#666666';
  }

  function getPriorityColor(priority) {
    const colors = {
      '緊急': '#cc0066',
      '高': '#ff6a00',
      '中': '#0066cc',
      '低': '#00aa44'
    };
    return colors[priority] || '#666666';
  }

  function getStatusColor(status) {
    const colors = {
      '未対応': '#ff6a00',
      '対応中': '#0066cc',
      '対応完了': '#00aa44',
      '保留': '#666666'
    };
    return colors[status] || '#666666';
  }

  // フィルター適用
  function applyFilters() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const errorType = container.querySelector('#error-type-filter').value;
    const system = container.querySelector('#system-filter').value;
    const status = container.querySelector('#status-filter').value;

    let filtered = [...currentErrors];

    if (startDate) {
      filtered = filtered.filter(e => e.エラー発生日時 >= startDate);
    }
    if (endDate) {
      filtered = filtered.filter(e => e.エラー発生日時 <= endDate + 'T23:59:59');
    }
    if (errorType) {
      filtered = filtered.filter(e => e.エラー種別 === errorType);
    }
    if (system) {
      filtered = filtered.filter(e => e.連携システム名 === system);
    }
    if (status) {
      filtered = filtered.filter(e => e.対応状況 === status);
    }

    renderErrors(filtered);
  }

  // エラー詳細表示
  function showErrorDetail(errorId) {
    const error = currentErrors.find(e => e.id === errorId);
    if (!error) return;

    selectedErrorId = errorId;
    const modal = container.querySelector('#error-detail-modal');
    const content = container.querySelector('#error-detail-content');

    content.innerHTML = `
      <div class="grid grid-cols-2 gap-3 text-sm">
        <div><span style="color: var(--text-muted);">エラーID:</span> ${error.id}</div>
        <div><span style="color: var(--text-muted);">発生日時:</span> ${new Date(error.エラー発生日時).toLocaleString()}</div>
        <div><span style="color: var(--text-muted);">エラー種別:</span> ${error.エラー種別}</div>
        <div><span style="color: var(--text-muted);">重要度:</span> ${error.重要度}</div>
        <div><span style="color: var(--text-muted);">発生箇所:</span> ${error.エラー発生箇所}</div>
        <div><span style="color: var(--text-muted);">エラーコード:</span> ${error.エラーコード || '-'}</div>
      </div>
      <div class="mt-3">
        <div class="text-xs mb-1" style="color: var(--text-muted);">エラーメッセージ</div>
        <div class="p-2 rounded text-sm" style="background: rgba(255,106,0,0.1); color: var(--text);">${error.エラーメッセージ}</div>
      </div>
      ${error.処理対象データ ? `
      <div class="mt-3">
        <div class="text-xs mb-1" style="color: var(--text-muted);">処理対象データ</div>
        <pre class="p-2 rounded text-xs overflow-x-auto" style="background: rgba(0,0,0,0.25); color: var(--text);">${error.処理対象データ}</pre>
      </div>
      ` : ''}
      ${error.スタックトレース ? `
      <div class="mt-3">
        <div class="text-xs mb-1" style="color: var(--text-muted);">スタックトレース</div>
        <pre class="p-2 rounded text-xs overflow-x-auto max-h-32" style="background: rgba(0,0,0,0.25); color: var(--text);">${error.スタックトレース}</pre>
      </div>
      ` : ''}
    `;

    container.querySelector('#status-update').value = error.対応状況;
    container.querySelector('#response-content').value = error.対応内容 || '';

    modal.style.display = 'flex';
  }

  // CSV出力
  function exportCSV() {
    const headers = ['発生日時', 'エラー種別', '連携システム', '対象データ', 'エラー内容', '重要度', '対応状況', '対応者'];
    const rows = currentErrors.map(error => [
      new Date(error.エラー発生日時).toLocaleString(),
      error.エラー種別,
      error.連携システム名 || '',
      error.発注データID ? `発注-${error.発注データID.slice(-8)}` : '',
      error.エラーメッセージ,
      error.重要度,
      error.対応状況,
      error.対応者名 || ''
    ]);

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `error_analysis_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    const errors = await window.aivicApi.list(6); // 連携エラーログ
    if (errors) {
      currentErrors = errors;
      renderErrors(errors);
    }
  }

  // イベントリスナー
  container.querySelector('#btn-filter').addEventListener('click', applyFilters);

  container.querySelector('#btn-refresh').addEventListener('click', loadData);

  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-reprocess').addEventListener('click', async () => {
    const unprocessedErrors = currentErrors.filter(e => e.対応状況 === '未対応' && e.再処理要否);
    if (unprocessedErrors.length === 0) {
      alert('再処理対象のエラーがありません。');
      return;
    }

    if (confirm(`${unprocessedErrors.length}件のエラーを再処理しますか？`)) {
      // 再処理ロジック（実際の実装では連携処理を実行）
      alert('再処理を開始しました。処理状況は連携処理履歴画面で確認してください。');
      window.showScreen('scr-1780291323940'); // 連携処理履歴画面
    }
  });

  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#error-detail-modal').style.display = 'none';
  });

  container.querySelector('#btn-update-status').addEventListener('click', async () => {
    if (!selectedErrorId) return;

    const status = container.querySelector('#status-update').value;
    const content = container.querySelector('#response-content').value;

    const updated = await window.aivicApi.update(6, selectedErrorId, {
      対応状況: status,
      対応内容: content,
      対応者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
      対応開始日時: status === '対応中' ? new Date().toISOString() : undefined,
      対応完了日時: status === '対応完了' ? new Date().toISOString() : undefined
    });

    if (updated) {
      container.querySelector('#error-detail-modal').style.display = 'none';
      loadData();
    }
  });

  container.querySelector('#btn-view-order').addEventListener('click', () => {
    const error = currentErrors.find(e => e.id === selectedErrorId);
    if (error && error.発注データID) {
      window.showScreen('scr-1780291283309'); // 発注データ管理画面
    } else {
      alert('関連する発注データがありません。');
    }
  });

  // 行クリックイベント
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showErrorDetail(detailBtn.dataset.id);
      return;
    }

    const reprocessBtn = e.target.closest('.reprocess-btn');
    if (reprocessBtn) {
      if (confirm('このエラーを再処理しますか？')) {
        // 個別再処理ロジック
        alert('再処理を開始しました。');
      }
      return;
    }

    const row = e.target.closest('tr[data-id]');
    if (row) {
      showErrorDetail(row.dataset.id);
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#error-detail-modal').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) {
      e.currentTarget.style.display = 'none';
    }
  });

  // 初期化
  loadData();
}

function(container, apiUrl, tables) {
  const validationResultsTable = tables.find(t => t.tableName === 'データ検証結果') || tables[7];
  const orderDataTable = tables.find(t => t.tableName === '発注データ') || tables[1];
  const validationRulesTable = tables.find(t => t.tableName === 'データ検証ルールマスタ') || tables[4];

  // 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector('#validation-results-tbody');
    tbody.innerHTML = rows.map(row => {
      const orderData = orderDataTable.records?.find(o => o.id === row.発注データID) || {};
      const validationRule = validationRulesTable.records?.find(r => r.id === row.検証ルールID) || {};

      const resultBadge = getResultBadge(row.検証結果 || '');
      const priorityBadge = getPriorityBadge(row.重要度 || '');
      const continueBadge = row.処理継続可否 ? 
        '<span class="px-2 py-1 text-xs rounded" style="background: #10b981; color: #fff;">可</span>' :
        '<span class="px-2 py-1 text-xs rounded" style="background: #ef4444; color: #fff;">不可</span>';

      return `
        <tr data-id="${row.id}" class="hover:bg-opacity-50" style="cursor: pointer;">
          <td class="text-sm">${formatDateTime(row.検証実行日時)}</td>
          <td class="text-sm font-medium">${orderData.発注番号 || '-'}</td>
          <td class="text-sm">${row.検証項目名 || '-'}</td>
          <td class="text-sm">${row.検証種別 || '-'}</td>
          <td>${resultBadge}</td>
          <td>${priorityBadge}</td>
          <td class="text-sm max-w-xs truncate" title="${row.検証メッセージ || ''}">${row.検証メッセージ || '-'}</td>
          <td>${continueBadge}</td>
          <td>
            <button class="action-btn secondary detail-btn text-xs px-2 py-1" data-id="${row.id}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    updateSummary(rows);
  }

  function getResultBadge(result) {
    const badges = {
      '成功': '<span class="px-2 py-1 text-xs rounded" style="background: #10b981; color: #fff;">成功</span>',
      '警告': '<span class="px-2 py-1 text-xs rounded" style="background: #f59e0b; color: #fff;">警告</span>',
      'エラー': '<span class="px-2 py-1 text-xs rounded" style="background: #ef4444; color: #fff;">エラー</span>'
    };
    return badges[result] || `<span class="px-2 py-1 text-xs rounded" style="background: var(--border); color: var(--text);">${result}</span>`;
  }

  function getPriorityBadge(priority) {
    const badges = {
      '高': '<span class="px-2 py-1 text-xs rounded" style="background: #ef4444; color: #fff;">高</span>',
      '中': '<span class="px-2 py-1 text-xs rounded" style="background: #f59e0b; color: #fff;">中</span>',
      '低': '<span class="px-2 py-1 text-xs rounded" style="background: #6b7280; color: #fff;">低</span>'
    };
    return badges[priority] || `<span class="px-2 py-1 text-xs rounded" style="background: var(--border); color: var(--text);">${priority}</span>`;
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  function updateSummary(rows) {
    const total = rows.length;
    const success = rows.filter(r => r.検証結果 === '成功').length;
    const warning = rows.filter(r => r.検証結果 === '警告').length;
    const error = rows.filter(r => r.検証結果 === 'エラー').length;

    container.querySelector('#total-count').textContent = total;
    container.querySelector('#success-count').textContent = success;
    container.querySelector('#warning-count').textContent = warning;
    container.querySelector('#error-count').textContent = error;
  }

  // 初期データ読み込み
  window.aivicApi.list(7).then(rows => {
    if (rows) renderRows(rows);
  });

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const keyword = container.querySelector('#input-search').value.toLowerCase();
    const resultFilter = container.querySelector('#filter-result').value;
    const priorityFilter = container.querySelector('#filter-priority').value;
    const typeFilter = container.querySelector('#filter-type').value;

    const rows = await window.aivicApi.list(7);
    if (!rows) return;

    const filtered = rows.filter(row => {
      const orderData = orderDataTable.records?.find(o => o.id === row.発注データID) || {};
      const matchKeyword = !keyword || 
        (orderData.発注番号 || '').toLowerCase().includes(keyword) ||
        (row.検証項目名 || '').toLowerCase().includes(keyword) ||
        (row.検証メッセージ || '').toLowerCase().includes(keyword);

      const matchResult = !resultFilter || row.検証結果 === resultFilter;
      const matchPriority = !priorityFilter || row.重要度 === priorityFilter;
      const matchType = !typeFilter || row.検証種別 === typeFilter;

      return matchKeyword && matchResult && matchPriority && matchType;
    });

    renderRows(filtered);
  });

  // 再検証実行
  container.querySelector('#btn-revalidate').addEventListener('click', async () => {
    if (!confirm('再検証を実行しますか？')) return;

    // 実際の再検証処理をシミュレート
    alert('再検証処理を開始しました。処理完了後に結果を更新します。');

    // データを再読み込み
    const rows = await window.aivicApi.list(7);
    if (rows) renderRows(rows);
  });

  // CSV出力
  container.querySelector('#btn-export-csv').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(7);
    if (!rows) return;

    const headers = ['検証日時', '発注番号', '検証項目名', '検証種別', '検証結果', '重要度', '検証メッセージ', '処理継続可否', '検証前値', '検証後値'];
    const csvData = [headers.join(',')];

    rows.forEach(row => {
      const orderData = orderDataTable.records?.find(o => o.id === row.発注データID) || {};
      const csvRow = [
        formatDateTime(row.検証実行日時),
        orderData.発注番号 || '',
        row.検証項目名 || '',
        row.検証種別 || '',
        row.検証結果 || '',
        row.重要度 || '',
        `"${(row.検証メッセージ || '').replace(/"/g, '""')}"`,
        row.処理継続可否 ? '可' : '不可',
        `"${(row.検証前値 || '').replace(/"/g, '""')}"`,
        `"${(row.検証後値 || '').replace(/"/g, '""')}"`,
      ];
      csvData.push(csvRow.join(','));
    });

    const blob = new Blob(['\uFEFF' + csvData.join('\n')], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `validation_results_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 詳細表示
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const rowId = detailBtn.dataset.id;
      showErrorDetail(rowId);
    }
  });

  async function showErrorDetail(rowId) {
    const rows = await window.aivicApi.list(7);
    const row = rows?.find(r => r.id === rowId);
    if (!row) return;

    container.querySelector('#modal-item-name').textContent = row.検証項目名 || '-';
    container.querySelector('#modal-validation-type').textContent = row.検証種別 || '-';
    container.querySelector('#modal-before-value').textContent = row.検証前値 || '-';
    container.querySelector('#modal-after-value').textContent = row.検証後値 || '-';
    container.querySelector('#modal-message').textContent = row.検証メッセージ || '-';

    container.querySelector('#error-detail-modal').style.display = 'flex';
  }

  // モーダル閉じる
  container.querySelector('#close-modal').addEventListener('click', () => {
    container.querySelector('#error-detail-modal').style.display = 'none';
  });

  container.querySelector('#modal-close').addEventListener('click', () => {
    container.querySelector('#error-detail-modal').style.display = 'none';
  });

  // 画面遷移
  container.addEventListener('click', (e) => {
    if (e.target.textContent?.includes('発注データ管理')) {
      window.showScreen('scr-1780291283309');
    } else if (e.target.textContent?.includes('連携処理')) {
      window.showScreen('scr-1780291294438');
    } else if (e.target.textContent?.includes('エラー分析')) {
      window.showScreen('scr-1780291305048');
    }
  });
}

function(container, apiUrl, tables) {
  const historyTable = tables.find(t => t.tableName === '連携処理履歴') || tables[0];
  const historyTableIndex = tables.indexOf(historyTable);

  // DOM要素の取得
  const tbody = container.querySelector('#history-tbody');
  const detailModal = container.querySelector('#detail-modal');

  // ステータス表示用の関数
  function getStatusBadge(status) {
    const colors = {
      '実行中': 'background: rgba(59, 130, 246, 0.2); color: #3b82f6; border: 1px solid rgba(59, 130, 246, 0.3);',
      '成功': 'background: rgba(34, 197, 94, 0.2); color: #22c55e; border: 1px solid rgba(34, 197, 94, 0.3);',
      '失敗': 'background: rgba(239, 68, 68, 0.2); color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.3);',
      '中断': 'background: rgba(251, 191, 36, 0.2); color: #fbbf24; border: 1px solid rgba(251, 191, 36, 0.3);',
      '再試行中': 'background: rgba(168, 85, 247, 0.2); color: #a855f7; border: 1px solid rgba(168, 85, 247, 0.3);'
    };
    const style = colors[status] || 'background: rgba(107, 114, 128, 0.2); color: #6b7280; border: 1px solid rgba(107, 114, 128, 0.3);';
    return `<span class="px-2 py-1 text-xs rounded" style="${style}">${status || '-'}</span>`;
  }

  // 処理時間計算
  function calculateDuration(start, end) {
    if (!start || !end) return '-';
    const startTime = new Date(start);
    const endTime = new Date(end);
    const diff = Math.floor((endTime - startTime) / 1000);
    if (diff < 60) return `${diff}秒`;
    if (diff < 3600) return `${Math.floor(diff / 60)}分${diff % 60}秒`;
    return `${Math.floor(diff / 3600)}時間${Math.floor((diff % 3600) / 60)}分`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}" class="cursor-pointer hover:bg-opacity-50" style="background: var(--bg-card);">
        <td class="text-sm">${row.処理開始日時 ? new Date(row.処理開始日時).toLocaleString('ja-JP') : '-'}</td>
        <td class="text-sm">${row.処理種別 || '-'}</td>
        <td>${getStatusBadge(row.処理ステータス)}</td>
        <td class="text-sm">${row.対象データID ? `ID: ${row.対象データID.slice(0, 8)}...` : '-'}</td>
        <td class="text-sm text-right">${row.処理件数 || 0}</td>
        <td class="text-sm text-right">${row.成功件数 || 0}</td>
        <td class="text-sm text-right">${row.エラー件数 || 0}</td>
        <td class="text-sm text-center">${row.再試行回数 || 0}</td>
        <td class="text-sm">${calculateDuration(row.処理開始日時, row.処理終了日時)}</td>
        <td>
          <button class="action-btn secondary detail-btn text-xs px-2 py-1" data-id="${row.id}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // 検索フィルター関数
  function filterRows(rows) {
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;
    const processType = container.querySelector('#filter-process-type').value;
    const status = container.querySelector('#filter-status').value;
    const orderNumber = container.querySelector('#filter-order-number').value.toLowerCase();

    return rows.filter(row => {
      // 日時範囲フィルター
      if (startDate && row.処理開始日時 && new Date(row.処理開始日時) < new Date(startDate)) return false;
      if (endDate && row.処理開始日時 && new Date(row.処理開始日時) > new Date(endDate)) return false;

      // 連携種別フィルター
      if (processType && row.処理種別 !== processType) return false;

      // ステータスフィルター
      if (status && row.処理ステータス !== status) return false;

      // 発注番号フィルター（対象データIDで検索）
      if (orderNumber && (!row.対象データID || !row.対象データID.toLowerCase().includes(orderNumber))) return false;

      return true;
    });
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    window.aivicApi.list(historyTableIndex).then(rows => {
      const history = rows.find(r => r.id === historyId);
      if (!history) return;

      // 基本情報の表示
      container.querySelector('#detail-id').textContent = history.id;
      container.querySelector('#detail-type').textContent = history.処理種別 || '-';
      container.querySelector('#detail-status').textContent = history.処理ステータス || '-';
      container.querySelector('#detail-start').textContent = history.処理開始日時 ? new Date(history.処理開始日時).toLocaleString('ja-JP') : '-';
      container.querySelector('#detail-end').textContent = history.処理終了日時 ? new Date(history.処理終了日時).toLocaleString('ja-JP') : '-';
      container.querySelector('#detail-total').textContent = history.処理件数 || 0;
      container.querySelector('#detail-success').textContent = history.成功件数 || 0;
      container.querySelector('#detail-error').textContent = history.エラー件数 || 0;
      container.querySelector('#detail-retry').textContent = history.再試行回数 || 0;

      // エラーメッセージの表示
      const errorSection = container.querySelector('#error-section');
      const errorMessage = container.querySelector('#error-message');
      if (history.エラーメッセージ) {
        errorMessage.textContent = history.エラーメッセージ;
        errorSection.style.display = 'block';
      } else {
        errorSection.style.display = 'none';
      }

      // リクエスト/レスポンスデータの表示
      container.querySelector('#request-data').textContent = history.リクエストデータ || '(データなし)';
      container.querySelector('#response-data').textContent = history.レスポンスデータ || '(データなし)';

      // 再実行ボタンの表示制御
      const retryBtn = container.querySelector('#btn-retry');
      if (history.処理ステータス === '失敗' || history.処理ステータス === '中断') {
        retryBtn.style.display = 'inline-block';
        retryBtn.dataset.historyId = historyId;
      } else {
        retryBtn.style.display = 'none';
      }

      detailModal.style.display = 'flex';
    });
  }

  // CSVエクスポート
  function exportCSV() {
    window.aivicApi.list(historyTableIndex).then(rows => {
      const headers = ['処理日時', '連携種別', '処理ステータス', '対象データID', '処理件数', '成功件数', 'エラー件数', '再試行回数', 'エラーメッセージ'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...rows.map(row => [
          row.処理開始日時 ? new Date(row.処理開始日時).toLocaleString('ja-JP') : '',
          row.処理種別 || '',
          row.処理ステータス || '',
          row.対象データID || '',
          row.処理件数 || 0,
          row.成功件数 || 0,
          row.エラー件数 || 0,
          row.再試行回数 || 0,
          `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `連携処理履歴_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();
    });
  }

  // 初期データの描画
  renderRows(historyTable.records || []);

  // 検索ボタンのイベントリスナー
  container.querySelector('#btn-search').addEventListener('click', () => {
    window.aivicApi.list(historyTableIndex).then(rows => {
      const filteredRows = filterRows(rows);
      renderRows(filteredRows);
    });
  });

  // クリアボタンのイベントリスナー
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    container.querySelector('#filter-process-type').value = '';
    container.querySelector('#filter-status').value = '';
    container.querySelector('#filter-order-number').value = '';
    window.aivicApi.list(historyTableIndex).then(renderRows);
  });

  // 更新ボタンのイベントリスナー
  container.querySelector('#btn-refresh').addEventListener('click', () => {
    window.aivicApi.list(historyTableIndex).then(renderRows);
  });

  // CSVエクスポートボタンのイベントリスナー
  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  // モーダル関連のイベントリスナー
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    detailModal.style.display = 'none';
  });

  // 詳細ボタンと再実行ボタンのイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
      return;
    }

    const retryBtn = e.target.closest('#btn-retry');
    if (retryBtn) {
      const historyId = retryBtn.dataset.historyId;
      if (confirm('この処理を再実行しますか？')) {
        // 再実行処理（実際の実装では基幹システム連携処理を呼び出す）
        alert('再実行処理を開始しました。');
        detailModal.style.display = 'none';
        window.aivicApi.list(historyTableIndex).then(renderRows);
      }
      return;
    }

    const validationBtn = e.target.closest('#btn-view-validation');
    if (validationBtn) {
      window.showScreen('scr-1780291315061'); // データ検証結果画面
      return;
    }

    const errorsBtn = e.target.closest('#btn-view-errors');
    if (errorsBtn) {
      window.showScreen('scr-1780291305048'); // 連携エラー分析画面
      return;
    }
  });

  // モーダル外クリックで閉じる
  detailModal.addEventListener('click', (e) => {
    if (e.target === detailModal) {
      detailModal.style.display = 'none';
    }
  });
}

function(container, apiUrl, tables) {
  // 通知設定テーブル（tableIndex: 9）と通知履歴テーブル（tableIndex: 10）
  const settingsTableIndex = 9; // システム通知設定
  const historyTableIndex = 10; // 通知履歴

  // 通知設定一覧の再描画関数
  function renderSettings(rows) {
    const tbody = container.querySelector("#settings-tbody");
    tbody.innerHTML = rows.map(r => {
      const priorityText = r.優先度 === 1 ? '高' : r.優先度 === 2 ? '中' : r.優先度 === 3 ? '低' : '';
      const statusBadge = r.有効フラグ ? 
        '<span style="background: #10b981; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">有効</span>' :
        '<span style="background: #6b7280; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">無効</span>';

      return `<tr data-id="${r.通知設定ID || r.id || ''}">
        <td>${r.通知名 || ''}</td>
        <td>${r.通知種別 || ''}</td>
        <td>${r.通知対象者種別 || ''}</td>
        <td>${r.通知方法 || ''}</td>
        <td>${priorityText}</td>
        <td>${statusBadge}</td>
        <td>${r.作成日時 ? new Date(r.作成日時).toLocaleDateString() : ''}</td>
        <td>
          <button class="action-btn secondary edit-settings-btn" data-id="${r.通知設定ID || r.id || ''}">編集</button>
          <button class="action-btn secondary delete-settings-btn" data-id="${r.通知設定ID || r.id || ''}">削除</button>
        </td>
      </tr>`;
    }).join("");
  }

  // 通知履歴一覧の再描画関数
  function renderHistory(rows) {
    const tbody = container.querySelector("#history-tbody");
    tbody.innerHTML = rows.map(r => {
      const statusBadge = r.送信状態 === '送信完了' ? 
        '<span style="background: #10b981; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">送信完了</span>' :
        r.送信状態 === '送信失敗' ?
        '<span style="background: #ef4444; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">送信失敗</span>' :
        '<span style="background: #f59e0b; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">送信待ち</span>';

      const priorityText = r.優先度 === '高' ? '高' : r.優先度 === '中' ? '中' : r.優先度 === '低' ? '低' : r.優先度 || '';
      const readStatus = r.既読フラグ ? '既読' : '未読';

      return `<tr data-id="${r.通知履歴ID || r.id || ''}">
        <td>${r.通知タイトル || ''}</td>
        <td>${r.通知種別 || ''}</td>
        <td>${r.受信者ユーザーID || ''}</td>
        <td>${r.送信方法 || ''}</td>
        <td>${statusBadge}</td>
        <td>${priorityText}</td>
        <td>${readStatus}</td>
        <td>${r.送信日時 ? new Date(r.送信日時).toLocaleDateString() : ''}</td>
        <td>
          <button class="action-btn secondary resend-btn" data-id="${r.通知履歴ID || r.id || ''}">再送</button>
        </td>
      </tr>`;
    }).join("");
  }

  // 初期データ表示
  renderSettings(tables[settingsTableIndex]?.records || []);
  renderHistory(tables[historyTableIndex]?.records || []);

  // 最新データを取得して表示
  window.aivicApi.list(settingsTableIndex).then(rows => {
    if (rows) renderSettings(rows);
  });

  window.aivicApi.list(historyTableIndex).then(rows => {
    if (rows) renderHistory(rows);
  });

  // 通知設定保存
  container.querySelector("#btn-save-notification").addEventListener("click", async () => {
    const notificationType = container.querySelector("#select-notification-type").value;
    const targetType = container.querySelector("#select-target-type").value;
    const notificationMethod = container.querySelector('input[name="notification-method"]:checked')?.value;
    const notificationName = container.querySelector("#input-notification-name").value;
    const priority = container.querySelector("#select-priority").value;
    const subjectTemplate = container.querySelector("#input-subject-template").value;
    const bodyTemplate = container.querySelector("#textarea-body-template").value;
    const condition = container.querySelector("#textarea-condition").value;
    const activeFlag = container.querySelector("#checkbox-active").checked;

    if (!notificationType || !targetType || !notificationMethod || !notificationName) {
      alert("必須項目を入力してください");
      return;
    }

    const data = {
      通知種別: notificationType,
      通知名: notificationName,
      通知対象者種別: targetType,
      通知方法: notificationMethod,
      件名テンプレート: subjectTemplate,
      本文テンプレート: bodyTemplate,
      発生条件: condition,
      優先度: parseInt(priority) || 2,
      有効フラグ: activeFlag,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(settingsTableIndex, data);
    if (saved) {
      const rows = await window.aivicApi.list(settingsTableIndex);
      if (rows) renderSettings(rows);

      // フォームクリア
      container.querySelector("#select-notification-type").value = "";
      container.querySelector("#select-target-type").value = "";
      container.querySelector("#input-notification-name").value = "";
      container.querySelector("#select-priority").value = "";
      container.querySelector("#input-subject-template").value = "";
      container.querySelector("#textarea-body-template").value = "";
      container.querySelector("#textarea-condition").value = "";
      container.querySelector("#checkbox-active").checked = false;
      const radioButtons = container.querySelectorAll('input[name="notification-method"]');
      radioButtons.forEach(radio => radio.checked = false);
    }
  });

  // フォームクリア
  container.querySelector("#btn-clear-form").addEventListener("click", () => {
    container.querySelector("#select-notification-type").value = "";
    container.querySelector("#select-target-type").value = "";
    container.querySelector("#input-notification-name").value = "";
    container.querySelector("#select-priority").value = "";
    container.querySelector("#input-subject-template").value = "";
    container.querySelector("#textarea-body-template").value = "";
    container.querySelector("#textarea-condition").value = "";
    container.querySelector("#checkbox-active").checked = false;
    const radioButtons = container.querySelectorAll('input[name="notification-method"]');
    radioButtons.forEach(radio => radio.checked = false);
  });

  // 通知設定検索
  container.querySelector("#btn-search-settings").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search-settings").value.toLowerCase();
    const rows = await window.aivicApi.list(settingsTableIndex);
    if (rows) {
      const filtered = rows.filter(r => 
        JSON.stringify(r).toLowerCase().includes(keyword)
      );
      renderSettings(filtered);
    }
  });

  // 通知履歴検索
  container.querySelector("#btn-search-history").addEventListener("click", async () => {
    const typeFilter = container.querySelector("#select-history-type").value;
    const statusFilter = container.querySelector("#select-send-status").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;

    const rows = await window.aivicApi.list(historyTableIndex);
    if (rows) {
      let filtered = rows;

      if (typeFilter) {
        filtered = filtered.filter(r => r.通知種別 === typeFilter);
      }

      if (statusFilter) {
        filtered = filtered.filter(r => r.送信状態 === statusFilter);
      }

      if (startDate) {
        filtered = filtered.filter(r => {
          const sendDate = r.送信日時 ? new Date(r.送信日時).toISOString().split('T')[0] : '';
          return sendDate >= startDate;
        });
      }

      if (endDate) {
        filtered = filtered.filter(r => {
          const sendDate = r.送信日時 ? new Date(r.送信日時).toISOString().split('T')[0] : '';
          return sendDate <= endDate;
        });
      }

      renderHistory(filtered);
    }
  });

  // CSVエクスポート
  container.querySelector("#btn-export-history").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(historyTableIndex);
    if (rows && rows.length > 0) {
      const headers = ['通知タイトル', '通知種別', '受信者', '送信方法', '送信状態', '優先度', '既読フラグ', '送信日時'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...rows.map(r => [
          `"${r.通知タイトル || ''}"`,
          `"${r.通知種別 || ''}"`,
          `"${r.受信者ユーザーID || ''}"`,
          `"${r.送信方法 || ''}"`,
          `"${r.送信状態 || ''}"`,
          `"${r.優先度 || ''}"`,
          `"${r.既読フラグ ? '既読' : '未読'}"`,
          `"${r.送信日時 || ''}"`
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `通知履歴_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    }
  });

  // テスト送信
  container.querySelector("#btn-test-send").addEventListener("click", async () => {
    const testData = {
      通知タイトル: 'テスト通知',
      通知内容: 'これはテスト送信です',
      通知種別: 'システムメンテナンス',
      優先度: '中',
      送信方法: 'システム内通知',
      送信状態: '送信完了',
      既読フラグ: false,
      受信者ユーザーID: 'test-user',
      送信日時: new Date().toISOString(),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(historyTableIndex, testData);
    if (saved) {
      alert('テスト通知を送信しました');
      const rows = await window.aivicApi.list(historyTableIndex);
      if (rows) renderHistory(rows);
    }
  });

  // イベントデリゲーション（編集・削除・再送）
  container.addEventListener("click", async (e) => {
    // 通知設定削除
    const deleteBtn = e.target.closest(".delete-settings-btn");
    if (deleteBtn) {
      if (!confirm("この通知設定を削除しますか？")) return;
      await window.aivicApi.delete(settingsTableIndex, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(settingsTableIndex);
      if (rows) renderSettings(rows);
      return;
    }

    // 通知設定編集
    const editBtn = e.target.closest(".edit-settings-btn");
    if (editBtn) {
      const rows = await window.aivicApi.list(settingsTableIndex);
      if (rows) {
        const record = rows.find(r => (r.通知設定ID || r.id) === editBtn.dataset.id);
        if (record) {
          container.querySelector("#select-notification-type").value = record.通知種別 || "";
          container.querySelector("#select-target-type").value = record.通知対象者種別 || "";
          container.querySelector("#input-notification-name").value = record.通知名 || "";
          container.querySelector("#select-priority").value = record.優先度 || "";
          container.querySelector("#input-subject-template").value = record.件名テンプレート || "";
          container.querySelector("#textarea-body-template").value = record.本文テンプレート || "";
          container.querySelector("#textarea-condition").value = record.発生条件 || "";
          container.querySelector("#checkbox-active").checked = record.有効フラグ || false;

          const methodRadio = container.querySelector(`input[name="notification-method"][value="${record.通知方法}"]`);
          if (methodRadio) methodRadio.checked = true;
        }
      }
      return;
    }

    // 通知再送
    const resendBtn = e.target.closest(".resend-btn");
    if (resendBtn) {
      if (!confirm("この通知を再送しますか？")) return;

      const rows = await window.aivicApi.list(historyTableIndex);
      if (rows) {
        const record = rows.find(r => (r.通知履歴ID || r.id) === resendBtn.dataset.id);
        if (record) {
          const updateData = {
            ...record,
            送信状態: '送信完了',
            送信日時: new Date().toISOString(),
            再送回数: (record.再送回数 || 0) + 1,
            更新日時: new Date().toISOString()
          };

          await window.aivicApi.update(historyTableIndex, resendBtn.dataset.id, updateData);
          const updatedRows = await window.aivicApi.list(historyTableIndex);
          if (updatedRows) renderHistory(updatedRows);
          alert('通知を再送しました');
        }
      }
      return;
    }
  });
}
